import {
    AfterViewInit,
    Component,
    EventEmitter,
    OnDestroy,
    OnInit,
    QueryList,
    ViewChild,
    ViewChildren
} from '@angular/core';
import {Title} from '@angular/platform-browser';
import {ActivatedRoute, Params, Router} from '@angular/router';
import {FormioComponent, FormioSubmission} from '@formio/angular';
import {Utils} from 'formiojs';
import {getConfig} from '../app-config';
import {AuthService} from '../auth/auth.service';
import {AppConstants} from '../constants/app.constants';
import {HeaderComponent} from '../header/header.component';
import {FormConfig} from '../service/form-config';
import {FormDraftSubmission, FormSubmission} from '../service/form-submission';
import {FormService} from '../service/form.service';
import {ProxyService} from '../service/proxy.service';
import _ = Utils._;

declare var $: any;

@Component({
    selector: 'app-form',
    templateUrl: './form.component.html',
    styleUrls: ['./form.component.scss']
})
export class FormComponent implements OnInit, OnDestroy, AfterViewInit {

    url = '';
    formName = '';
    stageName = '';
    hasFormName = false;
    submission: any = {};
    secured = false;
    refreshForm: any;
    uuid = '';
    reference: any;
    appId: any;
    sequence: any;
    formTitle = '';
    totaalbedrag: any;
    initdone = false;
    draftAutoSaveIntervalId: any;
    private formConfig: FormConfig | null;

    @ViewChild(HeaderComponent)
    private headerComponent: HeaderComponent | undefined;

    draftData: any;

    @ViewChildren('formioComponent')
    formioComponent: QueryList<FormioComponent> | undefined;

    formioComponentAfterRender: FormioComponent | undefined;

    pagesEmitter = new EventEmitter<any[]>();

    constructor(private formService: FormService,
                public route: ActivatedRoute,
                private proxyService: ProxyService,
                private authService: AuthService,
                private router: Router,
                private titleService: Title) {
        this.route.params
            .subscribe((params: Params) => {
                if (params.formName) {
                    this.hasFormName = true;
                    if (params.stageName) {
                        this.stageName = params.stageName;
                        this.url = getConfig().formStoreUrl + '/' + params.stageName + '/?form=' + params.formName;
                    }
                    this.formName = params.formName;
                }
            });
        this.formConfig = this.formService.getFormConfig();
    }

    ngAfterViewInit(): void {
        this.formioComponent?.changes.subscribe((formioComponent2: QueryList<FormioComponent>) => {

            this.formioComponentAfterRender = formioComponent2.first;

            formioComponent2.first.formioReady.then((formio) => {
                if (this.formConfig && this.formConfig.provisionalSavingAllowed && this.draftData) {
                    this.headerComponent?.setShowDraftModal(true);
                }

                window.location.hash = window.location.hash.substring(0, window.location.hash.lastIndexOf('/') + 1)
                    + 1;

                if (typeof formio.setPage === 'function') {
                    formio.setPage(0);
                }

                this.pagesEmitter.emit(formio.pages);

                window.onpopstate = (event: any) => {

                    if (window.location.hash.toUpperCase().includes(formio.form.name.toUpperCase())) {

                        const pageToGo = parseInt(window.location.hash.substring(window.location.hash.lastIndexOf('/') + 1));

                        if (isNaN(pageToGo) || pageToGo < 1 || formio._seenPages && Math.max(...formio._seenPages) + 2 < pageToGo) {
                            window.location.hash = window.location.hash.substring(0, window.location.hash.lastIndexOf('/') + 1)
                                + 1;
                        } else {
                            formio.setPage(pageToGo - 1);
                        }
                    } else {
                        // Als we uit het formulier gaan unbinden we alle events
                        window.onbeforeunload = null;
                        window.onpopstate = null;
                    }
                };
                const self = this;
                formio.on('navigateToNextPage', function() {

                    formio.nextPage().then((e: any) => {

                        self.pagesEmitter.emit(formio.pages)

                        const nextPage = formio.page + 1
                        const oldUrl = window.location.href;
                        const newHash = window.location.hash.substring(0, window.location.hash.lastIndexOf('/') + 1) + nextPage;

                        const newUrl = window.location.origin + '/' + newHash;

                        const titleWithSlash = window.location.hash.substring(1, window.location.hash.lastIndexOf('/'));
                        const title = titleWithSlash.substring(titleWithSlash.lastIndexOf('/'));

                        // @ts-ignore
                        _sz.push(['trackdynamic', {
                            url: newUrl.replace('#', 'hash'),
                            ref: oldUrl.replace('#', 'hash'),
                            title: title + '/' + newUrl.substring(newUrl.lastIndexOf('/') + 1)
                        }]);

                        window.location.hash = newHash;
                    });
                });
                formio.on('navigateToPrevPage', function() {
                    formio.prevPage().then((e: any) => {
                        const prevPage = formio.page + 1
                        self.pagesEmitter.emit(formio.pages)
                        const oldUrl = window.location.href;
                            const newHash = window.location.hash.substring(0, window.location.hash.lastIndexOf('/') + 1) + prevPage;

                        const newUrl = window.location.origin + '/' + newHash;

                        const titleWithSlash = window.location.hash.substring(1, window.location.hash.lastIndexOf('/'));
                        const title = titleWithSlash.substring(titleWithSlash.lastIndexOf('/'));
                        // @ts-ignore
                        _sz.push(['trackdynamic', {
                            url: newUrl.replace('#', 'hash'),
                            ref: oldUrl.replace('#', 'hash'),
                                title: title + '/' + newUrl.substring(newUrl.lastIndexOf('/') + 1)
                        }]);

                        window.location.hash = newHash;
                    });
                });

                formio.on('redraw', function() {
                    const closeButtons = $('.formio-button-remove-row');
                    for (const closeButton of closeButtons) {
                        const jqueryCloseButton = $(closeButton);
                        jqueryCloseButton.attr('aria-label', 'verwijderknop');
                    }
                });

                formio.on('pagesChanged', function() {
                    self.pagesEmitter.emit(formio.pages)
                });
            });
        });
    }

    scrollToTop(): void {
        window.scrollTo(0, 0);
    }

    getUrl(): string {
        return this.url;
    }

    async ngOnInit(): Promise<any> {
        this.secured = this.authService.isAuthenticated();
        if (this.secured) {
            await this.findDraft();
            this.uuid = this.draftData?.uuid;
        }
        // start with unique submission check
        if (this.secured) {
            const formConfig = this.formService.getFormConfig();
            if (formConfig && formConfig.uniqueSubmission && formConfig.uniqueSubmission.length > 0) {
               const data = await this.proxyService.uniqueSubmissionCheck(formConfig).toPromise();
               if (!data.status){
                    await this.router.navigateByUrl('unique-submission-error');
                    return;
                }
            }
        }
        this.refreshForm = new EventEmitter();
        if (!this.uuid) {
            this.uuid = await this.formService.setuuid().toPromise();
        }

        if (!this.reference) {
            this.appId = this.formService.getFormConfig()?.appId;
            const sequence = await this.formService.findReferenceSequence().toPromise();
            this.sequence = sequence.sequence;
            this.reference = this.appId + sequence.sequence;
        }
        if (this.authService.isAuthenticated()) {
            this.startDraftAutoSave();
        }
        this.initdone = true;
    }

    ngOnDestroy(): void {
        clearInterval(this.draftAutoSaveIntervalId);
    }

    async afterRender(event: any): Promise<any> {
        const formTitle = this.formioComponentAfterRender?.form?.title;
        if (formTitle){
            this.formTitle = formTitle;
        }
        this.titleService.setTitle(AppConstants.TITLE_PREFIX + this.formTitle);
        if (/iPad|iPhone|iPod/i.test(navigator.userAgent)) {
            const html = document.getElementsByTagName('html')[0];
            if (html && html.classList) {
                html.classList.add('device-iphone');
            }
        }

        // Datagrid hacks
        const datagrids = $('.formio-component-datagrid');
        for (const datagrid of datagrids) {
            const jquerydatagrid = $(datagrid);
            jquerydatagrid.children('.datagrid-table').attr('id', jquerydatagrid.children('.col-form-label').prop('htmlFor'));
        }
        const closeButtons = $('.formio-button-remove-row');
        for (const closeButton of closeButtons) {
            const jqueryCloseButton = $(closeButton);
            jqueryCloseButton.attr('aria-label', 'verwijderknop');
        }

        const logintypes = this.formService.getFormConfig()?.loginTypes;

        const user = this.authService.getCurrentProfile();
        if (user && user.loginmethod && logintypes) {
            logintypes.forEach(logintype => {
                if (logintype.authMethod === user.loginmethod) {
                    this.fillFieldData('inlogmiddelfield', logintype.authMethod);
                    this.fillFieldData('betrouwbaarheidsniveaufield', logintype.authMethod);
                }
            });
        }

        if (user) {
            this.fillFieldData('naamingelogdegebruikerfield', user.displayName);
            this.fillFieldData('naamingelogdegebruikerfieldnonhidden', user.displayName);
            if (!user.displayName) {
                const el = document.getElementsByClassName('naamingelogdegebruikerfieldnonhidden')?.item(0);
                el?.classList.add('emptynonhiddenfield');
            }
        }

        this.fillFieldData('uuidfield', this.uuid);
        this.fillFieldData('appIdField', this.appId);
        this.fillFieldData('kenmerkfield', this.appId + '-' + this.sequence);

        if (user && user.userData) {
            this.processUserData(user.userData);
            this.processUserDataNonHidden(user.userData);
        }

        this.addLangToNavigateButtons('btn-wizard-nav-next')
        this.addLangToNavigateButtons('btn-wizard-nav-previous')
        this.addLangToInputFields();
    }

    addLangToNavigateButtons(className : string) {
        const el = document.getElementsByClassName(className)?.item(0);
        if (el) {
            el.setAttribute("lang", "nl");
        }
    }

    addLangToInputFields() {
        const inputFields = document.getElementsByTagName('input')
        for(let i = 0; i < inputFields.length; i++) {
            inputFields[i].lang = 'nl';
        }
    }

    processUserData(userData: any): any {
        // Loop through all known userData
        for (const prop in userData) {
            if (Object.prototype.hasOwnProperty.call(userData, prop)) {
                this.fillFieldData(prop + 'field', userData[prop]);
            }
        }
    }

    processUserDataNonHidden(userData: any): any {
        // Loop through all non-hidden fields
        document.querySelectorAll('*[class*=fieldnonhidden]').forEach(el => {
            let prop = null;
            // Find the specific property name
            el.classList.forEach(n => {
                if (n.includes('fieldnonhidden')) {
                    prop = n.replace('fieldnonhidden', '');
                }
            });
            if (prop && Object.prototype.hasOwnProperty.call(userData, prop)) {
                this.fillFieldData(prop + 'fieldnonhidden', userData[prop]);
            } else if (!el.getAttribute('value')) {
                // When the element is not part of the userData then it will be hidden
                el.classList.add('emptynonhiddenfield');
            }
        });
    }

    fillFieldData(className: string, value: string): any {
        // Check whether the element exists on the form as a hidden field
        const el = document.getElementsByClassName(className)?.item(0);
        if (el) {
            // Get the form element to set the value
            const formEl = el.children?.item(1)?.children?.item(0) as HTMLInputElement;
            if (formEl) {
                formEl.value = value;
                formEl.dispatchEvent(new Event('input'));
            }
        }
    }

    async constructFormDraftSubmission(event: any): Promise<FormDraftSubmission> {
        const user = this.authService.getCurrentProfile();
        const formDraftSubmission: FormDraftSubmission = new FormDraftSubmission();
        formDraftSubmission.data = event.data;
        formDraftSubmission.form = this.formName;
        if (event.data.appId) {
            formDraftSubmission.reference = event.data.appId + this.sequence;
            formDraftSubmission.appId = event.data.appId;
        } else {
            formDraftSubmission.appId = this.formService.getFormConfig()?.appId;
            formDraftSubmission.reference = this.formService.getFormConfig()?.appId + this.sequence;
        }
        formDraftSubmission.uuid = this.uuid;
        formDraftSubmission.metadata = event.metadata;
        if (user) {
            formDraftSubmission.displayName = user.displayName;
            formDraftSubmission.loginmethod = user.loginmethod;
            formDraftSubmission.username = user.username;
            formDraftSubmission.initVectorEncryption = user.initVectorEncryption;
            if (user.kvkNr) {
                formDraftSubmission.kvkNr = user.kvkNr;
            }
        }
        formDraftSubmission.stage = this.stageName;
        formDraftSubmission.formTitle = this.formTitle;
        formDraftSubmission.redirectUrl = this.getCallbackUrl();

        return formDraftSubmission;
    }

    async onSubmit(event: any): Promise<any> {
        if (event.state === 'draft') {
            const formDraftSubmission: FormDraftSubmission = await this.constructFormDraftSubmission(event);
            this.saveDraft(formDraftSubmission);
            this.draftData = formDraftSubmission;
            document.querySelectorAll('.btn-primary .fa.fa-spin').forEach(spinner => {
                spinner.remove();
            });
            return;
        }

        window.onbeforeunload = null;
        window.onpopstate = null;
        $('#overlay').fadeIn().delay(10000).fadeOut();
        const formSubmission: FormSubmission = new FormSubmission();
        formSubmission.data = event.data;
        formSubmission.metadata = event.metadata;
        if (event.data.appId) {
            formSubmission.reference = event.data.appId + this.sequence;
            formSubmission.appId = event.data.appId;
        } else {
            formSubmission.reference = this.formService.getFormConfig()?.appId + this.sequence;
            formSubmission.appId = this.appId;
        }

        // @ts-ignore
        if (formSubmission.data.letOp) {
            // @ts-ignore
            delete formSubmission.data.letOp;
        }

        // remove the component from the submission data when it's conditional and non-visible
        this.removeConditionalNonVisibleFieldsFromSubmission(event);

        // always do a submit, but first set the totaalbedrag
        this.totaalbedrag = event.data.totaalbedrag;

        // @ts-ignore
        _sz.push(['trackdynamic', {
            url: window.location.href.replace('#', 'hash'),
            title: 'Formulier verzenden: ' + this.formTitle
        }]);

        this.formService.submit(formSubmission, this.secured, this.formName, this.stageName, this.uuid).subscribe({
            next: data => {
                // @ts-ignore
                _sz.push(['trackdynamic', {
                    title: 'Formulier verzonden: ' + this.formTitle
                }]);
                if (this.totaalbedrag && !isNaN(this.totaalbedrag) && this.totaalbedrag > 0) {
                    this.router.navigate(['/payment/start'], {queryParams: {uuid: this.uuid, formTitle: this.formTitle, reference: formSubmission.reference}});
                }else{
                    this.router.navigate(['/thanks'], {queryParams: {uuid: this.uuid, formTitle: this.formTitle, reference: formSubmission.reference}});
                }
            }
        });
    }

    onPageChanged(event: any): void {
        if (this.authService.isAuthenticated()) {
            this.constructAndSaveDraft(event.submission);
        }
        this.scrollToTop();
    }

    private removeConditionalNonVisibleFieldsFromSubmission(submission: FormioSubmission) {
        for (const property in submission.data) {
            if (this.shouldBeRemovedComponent(property)) {
                delete submission.data[property];
            }
        }
    }

    private shouldBeRemovedComponent(key: string): boolean {
        const allPages = this.formioComponentAfterRender?.formio?.allPages;
        for (let i = 0; i < allPages.length; i++) {
            const componentsOnPage = allPages[i].components
            const foundComponent = this.findComponentBySubmissionKey(key, componentsOnPage)
            if(foundComponent != null) {
                const isVisible = foundComponent.conditionallyVisible();
                const isRequired = foundComponent.component?.validate?.required;
                return isRequired && !isVisible;
            }
        }
        return true;
    }

    private findComponentBySubmissionKey(key: string, componentsArray: Array<any>): any|null {
        for (let j = 0; j < componentsArray.length; j++) {
            const currentComponent = componentsArray[j];
            if (currentComponent.path === key) {
                return currentComponent
            } else if(currentComponent.components?.length > 0) {
                const found = this.findComponentBySubmissionKey(key, currentComponent.components);
                if (found) return found;
            }
        }
        return null;
    }

    async constructAndSaveDraft(submission: any) {
        const formDraftSubmission: FormDraftSubmission = await this.constructFormDraftSubmission(submission);
        this.saveDraft(formDraftSubmission);
        this.draftData = formDraftSubmission;
        document.querySelectorAll('.btn-primary .fa.fa-spin').forEach(spinner => {
            spinner.remove();
        });
    }

    getCallbackUrl(): string {
        if (this.authService.isEmployee()) {
            return '/#/secure/employee';
        } else {
            return this.formService.getCallbackUrl();
        }

    }

    async onInput(event: any): Promise<any> {
        if (event && event.target && !event.target.placeholder.includes('__') && !event.target.className.includes('date-picker-input')) {
            const sanitized = this.sanitizeHTML(event.target.value);
            event.target.value = sanitized;
            event.target.dispatchEvent(new Event('input'));
        }
        if (event.target && event.target.id.endsWith('-postalcode')) {
            const postalcode = event.target.value.replace(/\s+/g, '');
            if (postalcode.match('[0-9]{4}[a-zA-Z]{2}') !== null) {

                this.proxyService.addressData(postalcode).subscribe((data: any) => {
                    if (_.isEmpty(data)) {
                        this.fillEmptyAddress(event);
                    } else {
                        this.fillValidAddress(event, data);
                    }
                }, error => {
                    // Als proxy service offline is of er een fout optreedt, enable disabled velden zodat gebruiker verder kan
                    const prefix = event.target.id.split('-postalcode')[0];
                    $(document.getElementById(prefix + '-streetname')).removeAttr('disabled');
                    $(document.getElementById(prefix + '-city')).removeAttr('disabled');
                });
            } else {
                this.fillEmptyAddress(event);
            }
        }
        if (event.changed && event.changed.component.key === 'bsn' && event.changed.value) {
            this.proxyService.addressData(event.changed.value).subscribe(
                (data: any) => {
                    event.data.brpdata = JSON.stringify(data); // data.Persoon.Persoonsgegevens.Achternaam;
                    event.data.lastname = data.Persoon.Persoonsgegevens.Achternaam;
                    this.refreshForm.emit({
                        submission: {
                            data: event.data
                        }
                    });
                });
        }
    }

    private sanitizeHTML(text: any) {
        {
            return text.replace(/<.*?>/g, '');
        }
    }

    private fillEmptyAddress(event: any) {
        const prefix = event.target.id.split('-postalcode')[0];
        $(document.getElementById(prefix + '-streetname')).val('');
        document.getElementById(prefix + '-streetname')!.dispatchEvent(new Event('input'));
        $(document.getElementById(prefix + '-city')).val('');
        document.getElementById(prefix + '-city')!.dispatchEvent(new Event('input'));
    }

    private fillValidAddress(event: any, data: any) {
        const prefix = event.target.id.split('-postalcode')[0];
        $(document.getElementById(prefix + '-streetname')).val(data.streetName);
        document.getElementById(prefix + '-streetname')!.dispatchEvent(new Event('input'));
        $(document.getElementById(prefix + '-city')).val(data.city);
        document.getElementById(prefix + '-city')!.dispatchEvent(new Event('input'));
    }

    private fillAddressFromDraft(data: any) {
        const prefix = 'adres_nijmegen';
        const elementsToUpdate = [];

        const streetNameElement = document.getElementById(prefix + '-streetname');
        if (streetNameElement) {
            $(streetNameElement).val(data[prefix][prefix + '-streetname']);
            elementsToUpdate.push(streetNameElement);
        }

        const cityElement = document.getElementById(prefix + '-city');
        if (cityElement) {
            $(cityElement).val(data[prefix][prefix + '-city']);
            elementsToUpdate.push(cityElement);
        }

        const postalCodeElement = document.getElementById(prefix + '-postalcode');
        if (postalCodeElement) {
            $(postalCodeElement).val(data[prefix][prefix + '-postalcode']);
            elementsToUpdate.push(postalCodeElement);
        }

        const houseNumberElement = document.getElementById(prefix + '-housenr');
        if (houseNumberElement) {
            $(houseNumberElement).val(data[prefix][prefix + '-housenr']);
            elementsToUpdate.push(houseNumberElement);
        }

        elementsToUpdate.forEach(element => {
            element!.dispatchEvent(new Event('input'));
        })
    }

    saveDraft(event: any): void {
        this.formService.draft(event).subscribe({
            next: data => {
                $('.savedraftbutton.btn-primary').children('.fa-spin').remove();
            },
            error: error => {
                $('.savedraftbutton.btn-primary').children('.fa-spin').remove();
            }
        });
    }

    async findDraft(): Promise<any> {
        const data: any = await this.formService.findDraft(this.formName).toPromise();
        if (data) {
            this.draftData = data;
        }
    }

    saveFormAsDraft(): any {
        this.constructAndSaveDraft(this.submission);
    }

    loadDraft(): any {
        if (this.draftData) {
            this.draftData.reference = this.reference; // use the next sequence for draft forms
            this.appId = this.draftData.appId;
            this.sequence = this.draftData.reference.replace(this.appId, '');
            this.uuid = this.draftData.uuid;
            this.submission = JSON.parse(JSON.stringify(this.draftData));
            this.fillAddressFromDraft(this.draftData.data);
        }
    }

    startDraftAutoSave() {
        this.draftAutoSaveIntervalId = setInterval(() => {
            this.constructAndSaveDraft(this.submission);
        }, 60 * 1000);
    }

}
