import { HttpClient, HttpErrorResponse, HttpHeaders } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { AbstractControl, ValidationErrors, ValidatorFn } from '@angular/forms';
import { Router } from '@angular/router';
import { CookieService } from 'ngx-cookie';
import { BehaviorSubject, Observable, throwError } from 'rxjs';
import { getConfig } from '../app-config';
import { AppConstants } from '../constants/app.constants';
import { FormConfig } from '../service/form-config';
import { UserProfile, UserProfileResponse } from './model/userProfile';

@Injectable({
    providedIn: 'root'
})
export class AuthService {
    private readonly environment = getConfig()

    private userProfileSubject: BehaviorSubject<UserProfile>;
    private isAuthenticatedSubject: BehaviorSubject<boolean>;

    public userProfileObservable: Observable<UserProfile>;
    public isAuthenticatedObservable: Observable<boolean>;

    private headers = new HttpHeaders()
        .set('content-type', 'application/json')
        .set('Access-Control-Allow-Origin', '*');

    constructor(
        private readonly httpClient: HttpClient,
        private router: Router,
        private cookieService: CookieService) {

        this.userProfileSubject = new BehaviorSubject<UserProfile>(new UserProfileResponse());
        this.isAuthenticatedSubject = new BehaviorSubject<boolean>(false);
        this.userProfileObservable = this.userProfileSubject.asObservable();
        this.isAuthenticatedObservable = this.isAuthenticatedSubject.asObservable();
    }

    public setIsAuthenticated(isAuthenticated: boolean): void {
        this.isAuthenticatedSubject.next(isAuthenticated);
    }

    public isAuthenticated(): boolean {
        return this.isAuthenticatedSubject.value;
    }

    public setUserProfileSubject(userProfile: UserProfile): void {
        this.userProfileSubject.next(userProfile);
    }

    public getCurrentProfile(): UserProfile {
        return this.userProfileSubject.value;
    }

    public isEmployee(): boolean {
        return this.userProfileSubject.value.loginmethod === 'microsoft';
    }

    login(formName: string): void {
        this.navigateToResponseUrl(`${this.environment.authenticationUrl}/auth/login?lang=nl&formname=` + formName);
    }

    loginEmployee(): void {
        this.navigateToResponseUrl(`${this.environment.authenticationUrl}/auth/login?lang=nl&employee=true`);
    }

    logout(): void {
        // do not remove FormConfig yet, because we need the callBackUrl after logout
        this.removeLocalUserdata(false);
        this.navigateToResponseUrl(`${this.environment.authenticationUrl}/public/logout`);
    }

    removeLocalUserdata(removeFormConfig: boolean): void{
        this.cookieService.remove(AppConstants.COOKIE_ACCESS_TOKEN);
        this.cookieService.remove(AppConstants.COOKIE_XSRF_TOKEN);
        this.cookieService.remove(AppConstants.COOKIE_UUID);
        localStorage.removeItem(AppConstants.COOKIE_ACCESS_TOKEN);
        if (removeFormConfig){
            localStorage.removeItem(AppConstants.FORM_CONFIG);
        }
        localStorage.removeItem(AppConstants.PKCE_VERIFIER);
        localStorage.removeItem(AppConstants.FORMIO_APP_USER);
        localStorage.removeItem(AppConstants.FORMIO_USER);

        this.cookieService.remove(AppConstants.JSESSIONID);

        this.userProfileSubject.next(new UserProfileResponse());
        this.isAuthenticatedSubject.next(false); // reset current user

    }

    // eslint-disable-next-line 
    loadUserProfile(enableRetry: boolean = false) {
        this.getUserProfile().subscribe({
            next: profile => {
                if (profile){
                    this.userProfileSubject.next(profile);
                    this.setIsAuthenticated(true);
                }
            },
            error: (error) => {
                if (enableRetry) {
                    console.warn('Refresh unsuccessful, retrying: ', error);
                    this.loadUserProfile();
                } else {
                    this.router.navigateByUrl('/error');
                }
            }
        });
    }

    // eslint-disable-next-line
    getUserProfile() {
        const httpOptions = {
            headers: new HttpHeaders({ 'Content-Type': 'application/json'}),
            withCredentials: true
        };

        const formConfig = this.getFormConfig();
        const configParam = formConfig ? '&formName=' + formConfig.formName : '';
        const burstParam = new Date().valueOf();
        return this.httpClient.get<any>(`${this.environment.authenticationUrl}/user/profile?t=${burstParam}${configParam}`, httpOptions);
    }

    getUserProfileAsEmployee(
        formName: string | undefined,
        identification: (string | (((control: AbstractControl) => (ValidationErrors | null)) | ValidatorFn)[])[]
    ): Observable<UserProfile> {
        const httpOptions = {
            headers: new HttpHeaders({ 'Content-Type': 'application/json'}),
            withCredentials: true
        };

        return this.httpClient.get<any>(
            `${this.environment.authenticationUrl}/user/profile?formName=` + formName + `&identification=` + identification,
            httpOptions
        );
    }

    getFormConfig(): FormConfig | null{
        const jsonFormAuthentication = localStorage.getItem(AppConstants.FORM_CONFIG);
        if (jsonFormAuthentication) {
            return JSON.parse(jsonFormAuthentication);
        }

        return null;
    }

    refreshToken(): void {
        this.loadUserProfile(true);
    }

    /*public setCurrentUser(authResponse: AuthResponse): void {
        this.currentUser = authResponse;
    }

    public getCurrentUser(): any {
        return this.currentUser;
    }
*/
    navigateToResponseUrl(url: string): void {
        window.location.href = url;
    }

    handleError(error: HttpErrorResponse): any {
        let errorMessage = 'Unknown error!';
        if (error.error instanceof ErrorEvent) {
            // Client-side errors
            errorMessage = `Error: ${error.error.message}`;
        } else {
            // Server-side errors
            errorMessage = `Error Code: ${error.status}\nMessage: ${error.message}`;
        }
        return throwError(errorMessage);
    }
}
